export const CHANNELS={payhere:'페이히어',otter:'오터',naver:'네이버'};
export function renderChannelAudit(a,ui,expanded=false){
 if(!a)return '';
 const {won,esc,nf}=ui,amount=n=>n===null?'미확인':won(n);
 return `<details class="card channel-audit" ${expanded?'open':''}><summary><span class="badge">원본 전체 검토</span> 2026년 1월부터 반영 범위·누락 확인 <span class="negative">총매출 대조 미완료</span></summary><div class="audit-body"><p>POS 상품 원본은 1월부터 있지만, 기존 총매출표에는 1~6월이 빠져 있습니다. 채널별 수집분과 기존 입력을 나란히 표시합니다. 아래 금액을 임의로 합쳐 연 누계로 확정하지 않습니다.</p><div class="audit-sources">${a.coverage.map(c=>`<article><b>${CHANNELS[c.channel]}</b><small>${c.start} ~ ${c.end}${c.itemStart?'<br>상품 상세 첫 관측 '+c.itemStart:''}</small><p>${esc(c.note)}</p></article>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>월</th><th class="num">페이히어 상품액</th><th class="num">그중 배달앱</th><th class="num">오터 주문액¹</th><th class="num">오터 상품 미확인</th><th class="num">네이버 완료액</th><th class="num">기존 총매출표</th><th>검토 상태</th></tr></thead><tbody>${a.months.map(m=>`<tr><td>${m.month}<small class="table-sub">POS ${m.posDays}일</small></td><td class="num">${amount(m.payhere)}</td><td class="num">${amount(m.posDelivery)}</td><td class="num">${amount(m.otter)}<small class="table-sub">${nf(m.otterOrders)}건 관측</small></td><td class="num">${amount(m.otterUnallocated)}<small class="table-sub">주문액에 포함</small></td><td class="num">${amount(m.naver)}<small class="table-sub">${nf(m.naverOrders)}건 관측</small></td><td class="num">${amount(m.legacy)}<small class="table-sub">${m.legacyDays}일 입력</small></td><td>${esc(m.status)}</td></tr>`).join('')}</tbody></table></div><div class="note"><b>검토 결과</b><br>① 1~6월: POS 원본은 확보했지만 전 채널 총매출표 누락.<br>② 7~8월: POS 배달앱과 오터의 중복 가능성 확인 필요.<br>③ 오터: 상세 미제공 193건, 변경·부분취소 상품 불일치 10건은 상품 미확인으로 분리.<br>④ 10월: 기존 매출 요약 화면과 주문 CSV의 기준 차이도 대조 필요. 기존 총매출표를 확정 금액으로 해석하지 마세요.<br>⑤ 2025년: POS 전체 확보, 오터·네이버 원본 관측 없음. 전 채널 전년 비교는 미확정입니다.</div><p class="sub">¹ 오터는 완료 주문 소계에 가맹점 할인 반영. 배달비·수수료 등이 섞인 CSV ‘합계’와 구분합니다. 상품 할인은 주문별 비례 배분합니다. 10월은 27일까지이며 28일 POS는 잠정 자료입니다. 첫 관측일 이전은 실제 0원으로 확정하지 않습니다. 시간대 자료는 POS 범위이며, 오터·네이버 전체 시간대 분석은 아직 제공하지 않습니다.</p><a class="btn small" href="channel-monthly-audit.csv" download>↓ 월별 검토표 CSV</a></div></details>`;
}
export function channelNote(a){return a?.policy||'채널 원본 반영 범위를 확인해 주세요.'}
